cat vitest.config.ts tsconfig.json; cat > src/claim-office.spec.ts <<'EOF'
import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("plain sword for newcomer → 100 base + 10 first insurance + 5 fee = 115 G");
    it.todo("plain amulet / staff / potion use their base premiums 60 / 80 / 40 G");
    it.todo("2 runes → 50 G base premium");
    it.todo("3 runes → 60 G base premium (block applies)");
    it.todo("4 runes → 100 G base premium (block requires exactly 3)");
    it.todo("7 runes → 175 G base premium");
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
    it.todo("newcomer with a cursed sword (enchantment 3) → premium 165 G");
    it.todo("cursed surcharge applies only to cursed item: cursed sword + plain amulet → 210 G before policy modifiers");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge");
    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies");
    it.todo("cursed sword with enchantment 5 → both surcharges apply");
    it.todo("customer with exactly 2 years → loyalty discount applies");
    it.todo("long-standing customer's second quote, cursed sword enchantment 7 → premium 160 G");
    it.todo("premium yielding 197.5 G → rounded up to 198 G");
    it.todo("quote with unknown item type (broomstick) → rejected with error");
  });

  describe("claim", () => {
    it.todo("regular steel sword, enchantment 3, damage 500 G → payout 400 G");
    it.todo("rune damage 200 G → payout 100 G");
    it.todo("claim reports remainingCap = 2 × insurance sum − payout");
    it.todo("steel sword enchantment 9, damage 1000 G → payout 400 G (50 % clause)");
    it.todo("dragon sword enchantment 5, damage 800 G → payout 700 G");
    it.todo("dragon sword enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
    it.todo("dragon sword exactly enchantment 8, damage 1000 G → payout 400 G");
    it.todo("dragon attack on sword (500) and amulet (300) → payout 600 G (deductible per damaged item)");
    it.todo("payout yielding 350.5 G → rounded down to 350 G");
    it.todo("sword + amulet policy → cap 3200 G");
    it.todo("cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
    it.todo("sword + 3 runes → insurance sum 1750 G, cap 3500 G");
    it.todo("two swords → cap 4000 G; two sword damages each with own deductible");
    it.todo("two successive 1500 G claims on a sword → 1400 G (remaining 600), then 600 G (remaining 0)");
    it.todo("more damage entries of a type than insured → claim rejected");
    it.todo("damage to item not in the policy → rejected with error");
    it.todo("damage with unknown item type → rejected with error");
    it.todo("damage with negative amount → rejected with error");
  });

  describe("CLI", () => {
    it.todo("reads scenario JSON from stdin and writes results JSON to stdout");
    it.todo("exits non-zero with error on stderr and no results on stdout for invalid input");
  });
});
EOF

