export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
};

export type Result = { premium: number } | { payout: number; remainingCap: number };

export type ScenarioResults = { results: Result[] };

const PROCESSING_FEE = 5;
const BASE_PREMIUMS: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40, rune: 25 };

const sum = (amounts: number[]): number => amounts.reduce((total, amount) => total + amount, 0);

const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];

const quotePremium = (items: Item[]): number => {
  const basePremium = sum(items.map(basePremiumOf));
  const firstInsuranceSurcharge = basePremium / 10;
  return basePremium + firstInsuranceSurcharge + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: [{ premium: quotePremium(scenario.steps[0].items) }],
});

